-- Team: 国足世界杯夺冠队
-- Coding by 李行阳 2411353, 20261117
-- 模块:届次与比赛 —— 1986~2022 真实世界杯比赛数据
-- 数据来源:https://github.com/openfootball/worldcup (CC0-1.0, more/*_full.txt、more/*_squads.txt); https://github.com/martj42/international_results (CC0-1.0, results.csv / goalscorers.csv)
--   1) https://github.com/openfootball/worldcup (CC0-1.0 Universal)
--      more/1986_full.txt ~ more/2022_full.txt(比赛、进球、出场阵容)
--      more/1986_squads.txt ~ more/2022_squads.txt(生日、位置、球衣号)
--      2018 届点球/乌龙标记以同仓库 2018--russia/cup.txt、cup_finals.txt 为准。
--   2) https://github.com/martj42/international_results (CC0-1.0 Universal)
--      results.csv / goalscorers.csv:用于 604 场比赛比分交叉校验、
--      补齐 openfootball 2018 详情文件缺失的点球/乌龙标记,并补充助攻(assist)。
--
-- 文件:data/real_worldcup_data.sql
-- 用法:先导入 data/install.sql,再导入本文件(建议在干净库中验证):
--   mysql --default-character-set=utf8mb4 -u root -p worldcup < data/real_worldcup_data.sql
--
-- 覆盖:1986/1990/1994/1998/2002/2006/2010/2014/2018/2022 共 10 届。
--   1986: 52 场, 120分钟进球 132 个, 点球大战进球 21 个
--   1990: 52 场, 120分钟进球 115 个, 点球大战进球 28 个
--   1994: 52 场, 120分钟进球 141 个, 点球大战进球 18 个
--   1998: 64 场, 120分钟进球 171 个, 点球大战进球 20 个
--   2002: 64 场, 120分钟进球 161 个, 点球大战进球 13 个
--   2006: 64 场, 120分钟进球 147 个, 点球大战进球 21 个
--   2010: 64 场, 120分钟进球 145 个, 点球大战进球 14 个
--   2014: 64 场, 120分钟进球 171 个, 点球大战进球 26 个
--   2018: 64 场, 120分钟进球 169 个, 点球大战进球 26 个
--   2022: 64 场, 120分钟进球 172 个, 点球大战进球 26 个
--
-- 说明:
--   1. 比赛与比分 100% 取自 openfootball 的 Football.TXT 数据集;
--      球队按当时历史身份命名(西德/苏联/捷克斯洛伐克/南斯拉夫/塞黑 不与现代国家合并)。
--   2. home_score/away_score 为 120 分钟(含加时)比分;点球大战比分单独写入
--      home_penalty_score/away_penalty_score;点球大战进球 is_shootout=1、minute=NULL,
--      按本项目既有约定 is_penalty=0,统计时排除。
--   3. 进球分钟按来源的“基础分钟”记录(如 45+3' 记为 45,90+9' 记为 90),
--      以满足 goal.minute 1~130 的整数约束;点球大战不记分钟。
--   4. 助攻来自 martj42/international_results 的 goalscorers.csv;仅当该表给出助攻且
--      能匹配到该队实际出场球员时才写入,匹配不到的 14 个助攻留 NULL,没有编造。
--      点球大战与乌龙球不写助攻。
--   5. 球员/参赛名单只包含该届该队实际出场(首发或替补登场)的球员;
--      球衣号、生日、位置来自同仓库 squads.txt;匹配不到的真实出场球员保留姓名,
--      birth_date/shirt_number 留 NULL,不编造。
--   6. tournament_team 只填 group_name;coach/fifa_rank/final_rank 无可靠来源,留 NULL。
--   7. 幂等:所有插入均带 NOT EXISTS 判重,不删除、不覆盖已有数据。
--      唯一例外:若检测到现有 2022 演示决赛“巴西 vs 西班牙”,会先清理该届 13 场演示比赛
--      及 8 支演示球队的 2022 届 squad/tournament_team 行,以便写入真实 2022 数据;
--      其他届次的演示数据一律不删除、不修改。
--   8. 若库里已有 data/demo_history_data.sql 的 1986~2018 演示数据,真实比赛/名单可能与
--      其冲突(演示数据本身是近似值)。本文件会跳过已存在的比赛,并对冲突的球衣号回退为 NULL;
--      要做完整替换,请先在测试库中清空旧演示数据再导入本文件。
--   9. 604 场比赛的日期、球队、120 分钟比分已与 martj42 数据集逐场交叉校验,全部一致;
--      1524 个非点球大战进球的每场数量也完全一致。

SET NAMES utf8mb4 COLLATE utf8mb4_unicode_ci;

START TRANSACTION;

-- ---------------------------------------------------------------------------
-- 0. 清理 2022 演示数据(仅在检测到演示决赛 巴西 vs 西班牙 时执行)
-- ---------------------------------------------------------------------------
SET @wc_2022_demo = (
    SELECT COUNT(*) FROM game g
    JOIN tournament t ON t.id = g.tournament_id
    JOIN team h ON h.id = g.home_team_id
    JOIN team a ON a.id = g.away_team_id
    WHERE t.year = 2022 AND g.stage = '决赛'
      AND h.name = '巴西' AND a.name = '西班牙'
);

-- 13 场演示比赛(12 场小组赛 + 1 场决赛)
DELETE g FROM game g
JOIN tournament t ON t.id = g.tournament_id
JOIN team h ON h.id = g.home_team_id
JOIN team a ON a.id = g.away_team_id
WHERE @wc_2022_demo > 0 AND t.year = 2022 AND (
      (h.name = '巴西'   AND a.name IN ('德国','日本','摩洛哥','西班牙'))
   OR (h.name = '日本'   AND a.name = '摩洛哥')
   OR (h.name = '德国'   AND a.name IN ('摩洛哥','日本'))
   OR (h.name = '西班牙' AND a.name IN ('克罗地亚','英格兰','荷兰'))
   OR (h.name = '英格兰' AND a.name = '荷兰')
   OR (h.name = '克罗地亚' AND a.name = '荷兰')
   OR (h.name = '克罗地亚' AND a.name = '英格兰')
);

DELETE s FROM squad s
JOIN tournament t ON t.id = s.tournament_id
JOIN team tm ON tm.id = s.team_id
WHERE @wc_2022_demo > 0 AND t.year = 2022 AND tm.name IN ('巴西','德国','日本','摩洛哥','西班牙','克罗地亚','英格兰','荷兰');

DELETE tt FROM tournament_team tt
JOIN tournament t ON t.id = tt.tournament_id
JOIN team tm ON tm.id = tt.team_id
WHERE @wc_2022_demo > 0 AND t.year = 2022 AND tm.name IN ('巴西','德国','日本','摩洛哥','西班牙','克罗地亚','英格兰','荷兰');

-- ---------------------------------------------------------------------------
-- 1. 球队(仅补充不存在的新球队;已有球队按 code / name 复用)
-- ---------------------------------------------------------------------------
DROP TEMPORARY TABLE IF EXISTS tmp_real_team;
