    src varchar(60) NOT NULL,
    name varchar(50) NOT NULL,
    code varchar(10) NOT NULL,
    continent varchar(20) DEFAULT NULL,
    PRIMARY KEY (src)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;

