INSERT INTO tournament_team (tournament_id, team_id, group_name)
SELECT tr.id, tm.team_id, d.group_name
FROM tmp_real_tt d
JOIN tournament tr ON tr.year = d.year
JOIN tmp_real_team_map tm ON tm.src = d.team_src
WHERE NOT EXISTS (
    SELECT 1 FROM tournament_team x
    WHERE x.tournament_id = tr.id AND x.team_id = tm.team_id
);

-- 2022 演示数据若已存在,修正其小组名(只影响 2022,其他届次不动)
UPDATE tournament_team tt
JOIN tournament tr ON tr.id = tt.tournament_id AND tr.year = 2022
JOIN tmp_real_team_map tm ON tm.team_id = tt.team_id
JOIN tmp_real_tt d ON d.year = 2022 AND d.team_src = tm.src
SET tt.group_name = d.group_name
WHERE tt.group_name IS NULL OR tt.group_name <> d.group_name;

-- ---------------------------------------------------------------------------
-- 3. 球员(只包含数据集中实际出场/进球的真实球员)
-- ---------------------------------------------------------------------------
DROP TEMPORARY TABLE IF EXISTS tmp_real_player;
CREATE TEMPORARY TABLE tmp_real_player (
    pkey varchar(120) NOT NULL,
    name varchar(50) NOT NULL,
    nat varchar(50) NOT NULL,
    birth date DEFAULT NULL,
    position varchar(20) DEFAULT NULL,
    PRIMARY KEY (pkey)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;

