INSERT INTO player (name, birth_date, nationality, position)
SELECT d.name, d.birth, d.nat, d.position
FROM tmp_real_player d
WHERE NOT EXISTS (
    SELECT 1 FROM player p WHERE p.name = d.name AND p.nationality = d.nat
);

DROP TEMPORARY TABLE IF EXISTS tmp_real_player_map;
CREATE TEMPORARY TABLE tmp_real_player_map (
    pkey varchar(120) NOT NULL,
    player_id int NOT NULL,
    PRIMARY KEY (pkey)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;
INSERT INTO tmp_real_player_map (pkey, player_id)
SELECT d.pkey, MIN(p.id)
FROM tmp_real_player d
JOIN player p ON p.name = d.name AND p.nationality = d.nat
GROUP BY d.pkey;

-- ---------------------------------------------------------------------------
-- 4. 参赛名单(该届该队实际出场球员;球衣号来自 squads.txt)
-- ---------------------------------------------------------------------------
DROP TEMPORARY TABLE IF EXISTS tmp_real_squad;
CREATE TEMPORARY TABLE tmp_real_squad (
    year int NOT NULL,
    team_src varchar(60) NOT NULL,
    pkey varchar(120) NOT NULL,
    shirt_number int DEFAULT NULL,
    position varchar(20) DEFAULT NULL,
    PRIMARY KEY (year, team_src, pkey)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;

