-- 4.1 先插入球衣号不冲突的球员
INSERT INTO squad (tournament_id, team_id, player_id, shirt_number, position)
SELECT tr.id, tm.team_id, pm.player_id, d.shirt_number, d.position
FROM tmp_real_squad d
JOIN tournament tr ON tr.year = d.year
JOIN tmp_real_team_map tm ON tm.src = d.team_src
JOIN tmp_real_player_map pm ON pm.pkey = d.pkey
WHERE d.shirt_number IS NOT NULL
  AND NOT EXISTS (
      SELECT 1 FROM squad s
      WHERE s.tournament_id = tr.id AND s.player_id = pm.player_id
  )
  AND NOT EXISTS (
      SELECT 1 FROM squad s2
      WHERE s2.tournament_id = tr.id AND s2.team_id = tm.team_id
        AND s2.shirt_number = d.shirt_number
  );

-- 4.2 再插入没有球衣号或球衣号与已有数据冲突的球员(号码置 NULL,不修改已有行)
INSERT INTO squad (tournament_id, team_id, player_id, shirt_number, position)
SELECT tr.id, tm.team_id, pm.player_id, NULL, d.position
FROM tmp_real_squad d
JOIN tournament tr ON tr.year = d.year
JOIN tmp_real_team_map tm ON tm.src = d.team_src
JOIN tmp_real_player_map pm ON pm.pkey = d.pkey
WHERE NOT EXISTS (
      SELECT 1 FROM squad s
      WHERE s.tournament_id = tr.id AND s.player_id = pm.player_id
  )
  AND (d.shirt_number IS NULL OR EXISTS (
      SELECT 1 FROM squad s2
      WHERE s2.tournament_id = tr.id AND s2.team_id = tm.team_id
        AND s2.shirt_number = d.shirt_number
  ));

-- ---------------------------------------------------------------------------
-- 5. 比赛
-- ---------------------------------------------------------------------------
DROP TEMPORARY TABLE IF EXISTS tmp_real_game;
CREATE TEMPORARY TABLE tmp_real_game (
    year int NOT NULL,
    stage varchar(20) NOT NULL,
    home_src varchar(60) NOT NULL,
    away_src varchar(60) NOT NULL,
    home_score int NOT NULL,
    away_score int NOT NULL,
    home_penalty_score tinyint unsigned DEFAULT NULL,
    away_penalty_score tinyint unsigned DEFAULT NULL,
    match_time datetime DEFAULT NULL,
    venue varchar(50) DEFAULT NULL,
    home_team_id int DEFAULT NULL,
    away_team_id int DEFAULT NULL,
    PRIMARY KEY (year, stage, home_src, away_src)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;

