-- 分步解析球队 id,避免同一临时表在一条语句中被多次打开
UPDATE tmp_real_game d
JOIN tmp_real_team_map hm ON hm.src = d.home_src
SET d.home_team_id = hm.team_id;

UPDATE tmp_real_game d
JOIN tmp_real_team_map am ON am.src = d.away_src
SET d.away_team_id = am.team_id;

INSERT INTO game (tournament_id, home_team_id, away_team_id, home_score, away_score,
    home_penalty_score, away_penalty_score, match_time, stage, venue, status)
SELECT tr.id, d.home_team_id, d.away_team_id, d.home_score, d.away_score,
       d.home_penalty_score, d.away_penalty_score, d.match_time, d.stage, d.venue, 2
FROM tmp_real_game d
JOIN tournament tr ON tr.year = d.year
WHERE d.home_team_id IS NOT NULL AND d.away_team_id IS NOT NULL
  AND NOT EXISTS (
    SELECT 1 FROM game g
    WHERE g.tournament_id = tr.id
      AND g.home_team_id = d.home_team_id
      AND g.away_team_id = d.away_team_id
      AND g.stage = d.stage
);

-- ---------------------------------------------------------------------------
-- 6. 进球(含点球大战进球;assist_player_id 无来源,全部 NULL)
-- ---------------------------------------------------------------------------
DROP TEMPORARY TABLE IF EXISTS tmp_real_goal;
CREATE TEMPORARY TABLE tmp_real_goal (
    seq int NOT NULL AUTO_INCREMENT,
    year int NOT NULL,
    stage varchar(20) NOT NULL,
    home_src varchar(60) NOT NULL,
    away_src varchar(60) NOT NULL,
    team_src varchar(60) NOT NULL,
    pkey varchar(120) NOT NULL,
    minute int DEFAULT NULL,
    is_penalty tinyint NOT NULL DEFAULT 0,
    is_own_goal tinyint NOT NULL DEFAULT 0,
    is_shootout tinyint NOT NULL DEFAULT 0,
    assist_key varchar(120) DEFAULT NULL,
    home_team_id int DEFAULT NULL,
    away_team_id int DEFAULT NULL,
    team_id int DEFAULT NULL,
    player_id int DEFAULT NULL,
    assist_player_id int DEFAULT NULL,
    game_id int DEFAULT NULL,
    PRIMARY KEY (seq),
    KEY idx_goal_nat (year, stage, home_src, away_src, pkey)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;

