-- 分步解析球队 / 球员 / 比赛 id,避免同一临时表在一条语句中被多次打开
UPDATE tmp_real_goal d
JOIN tmp_real_team_map hm ON hm.src = d.home_src
SET d.home_team_id = hm.team_id;

UPDATE tmp_real_goal d
JOIN tmp_real_team_map am ON am.src = d.away_src
SET d.away_team_id = am.team_id;

UPDATE tmp_real_goal d
JOIN tmp_real_team_map tm ON tm.src = d.team_src
SET d.team_id = tm.team_id;

UPDATE tmp_real_goal d
JOIN tmp_real_player_map pm ON pm.pkey = d.pkey
SET d.player_id = pm.player_id;

UPDATE tmp_real_goal d
JOIN tmp_real_player_map am ON am.pkey = d.assist_key
SET d.assist_player_id = am.player_id;

UPDATE tmp_real_goal d
JOIN tournament tr ON tr.year = d.year
JOIN game g ON g.tournament_id = tr.id
           AND g.home_team_id = d.home_team_id
           AND g.away_team_id = d.away_team_id
           AND g.stage = d.stage
SET d.game_id = g.id;

INSERT INTO goal (game_id, team_id, player_id, assist_player_id, minute,
    is_penalty, is_own_goal, is_shootout)
SELECT d.game_id, d.team_id, d.player_id, d.assist_player_id, d.minute,
       d.is_penalty, d.is_own_goal, d.is_shootout
FROM tmp_real_goal d
WHERE d.game_id IS NOT NULL AND d.team_id IS NOT NULL AND d.player_id IS NOT NULL
  AND NOT EXISTS (
    SELECT 1 FROM goal x
    WHERE x.game_id = d.game_id
      AND x.player_id = d.player_id
      AND x.minute <=> d.minute
      AND x.is_penalty = d.is_penalty
      AND x.is_own_goal = d.is_own_goal
      AND x.is_shootout = d.is_shootout
);

COMMIT;

DROP TEMPORARY TABLE IF EXISTS tmp_real_goal;
DROP TEMPORARY TABLE IF EXISTS tmp_real_game;
DROP TEMPORARY TABLE IF EXISTS tmp_real_squad;
DROP TEMPORARY TABLE IF EXISTS tmp_real_player_map;
DROP TEMPORARY TABLE IF EXISTS tmp_real_player;
DROP TEMPORARY TABLE IF EXISTS tmp_real_tt;
DROP TEMPORARY TABLE IF EXISTS tmp_real_team_map;
DROP TEMPORARY TABLE IF EXISTS tmp_real_team;

